<?php
namespace App\Http\Controllers;
use App\Models\Workspace;
use App\Services\WorkspaceContext;
use App\Services\FinanceAccess as F;
use App\Services\Identity;
use App\Services\TeamAccess;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Validation\ValidationException;
class FinanceController {
 public function __construct(private WorkspaceContext $context){}
 private function workspace(Request $r):Workspace{$w=$this->context->current($r);F::authorize($w,$r->user());return $w;}
 private function today(Request $r):string{return now()->setTimezone($r->user()->timezone?:'UTC')->toDateString();}
 private function fail(string $key,string $message):never{throw ValidationException::withMessages([$key=>$message]);}
 private function change(Request $r,string $event,callable $fn){$w=$this->workspace($r);DB::transaction(function()use($r,$w,$event,$fn){$w=F::lock($w,$r->user());$fn($w);Identity::audit('finance_'.$event,$r->user(),$w);});return back()->with('status','Financial record saved.');}
 private function business(Workspace $w):void{abort_unless($w->type==='business',403);}
 private function positive(mixed $v):int{$n=F::minor($v);if($n<=0)$this->fail('amount','Amount must be positive.');return $n;}
 private function dateRule(Request $r):string{return 'required|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:'.$this->today($r);}
 private function monthRule():string{return 'required|date_format:Y-m|after_or_equal:2000-01|before_or_equal:2100-12';}
 private function end(string $month):string{return \Illuminate\Support\Carbon::createFromFormat('!Y-m',$month,'UTC')->endOfMonth()->toDateString();}
 private function month(Request $r):string{return $r->validate(['month'=>'nullable|date_format:Y-m|after_or_equal:2000-01|before_or_equal:2100-12'])['month']??substr($this->today($r),0,7);}
 public function index(Request $r){
  $w=$this->workspace($r);$month=$this->month($r);$today=$this->today($r);$stats=F::stats($w,$r->user(),$month);
  $accounts=F::query($w,'accounts')->orderBy('name')->get();$categories=F::query($w,'categories')->orderBy('name')->get();
  $balances=F::query($w,'transactions')->selectRaw("account_id, SUM(CASE WHEN kind='income' THEN CAST(amount_minor AS SIGNED) ELSE -CAST(amount_minor AS SIGNED) END) AS balance")->groupBy('account_id')->pluck('balance','account_id');
  $transactions=F::query($w,'transactions')->whereBetween('local_date',[$month.'-01',$this->end($month)])->latest('local_date')->latest('id')->paginate(30,['*'],'transactions')->withQueryString();
  $receipts=F::query($w,'receipts')->whereIn('transaction_id',$transactions->pluck('id'))->get(['id','transaction_id','name'])->groupBy('transaction_id');$reversed=F::query($w,'transactions')->whereIn('reversal_of',$transactions->pluck('id'))->pluck('reversal_of')->all();
  $recurring=F::query($w,'recurring')->latest('id')->paginate(20,['*'],'recurring')->withQueryString();$rates=F::query($w,'rates')->latest('local_date')->paginate(20,['*'],'rates')->withQueryString();
  $budgets=F::query($w,'budgets')->where('month',$month.'-01')->paginate(20,['*'],'budgets')->withQueryString();
  $spent=F::query($w,'transactions')->whereBetween('local_date',[$month.'-01',$this->end($month)])->selectRaw("category_id,currency,SUM(CASE WHEN kind='expense' AND reversal_of IS NULL THEN CAST(amount_minor AS SIGNED) WHEN kind='income' AND reversal_of IS NOT NULL THEN -CAST(amount_minor AS SIGNED) ELSE 0 END) AS spent")->groupBy('category_id','currency')->get()->keyBy(fn($x)=>$x->category_id.':'.$x->currency);
  $savings=F::query($w,'savings')->latest('id')->paginate(20,['*'],'savings')->withQueryString();
  $employees=$w->type==='business'?$w->members()->get(['users.id','users.name'])->filter(fn($u)=>$w->roleFor($u)!==null)->values():collect();
  $salaries=F::query($w,'salaries')->latest('id')->paginate(20,['*'],'salaries')->withQueryString();$payroll=F::query($w,'payroll')->where('month',$month.'-01')->paginate(20,['*'],'payroll')->withQueryString();$invoices=F::query($w,'invoices')->latest('id')->paginate(20,['*'],'invoices')->withQueryString();
  $contacts=$w->type==='business'?DB::table('crm_contacts')->where('workspace_id',$w->id)->orderBy('name')->get(['id','name']):collect();$names=$employees->pluck('name','id');$linked=F::query($w,'payroll')->whereIn('transaction_id',$transactions->pluck('id'))->pluck('transaction_id')->merge(F::query($w,'invoices')->whereIn('transaction_id',$transactions->pluck('id'))->pluck('transaction_id'))->all();
  return view('finance.index',compact('w','month','today','stats','accounts','categories','balances','transactions','receipts','reversed','recurring','rates','budgets','spent','savings','employees','salaries','payroll','invoices','contacts','names','linked'));
 }
 public function account(Request $r){$this->workspace($r);$d=$r->validate(['name'=>'required|string|max:120','kind'=>'required|in:cash,bank,wallet','currency'=>'required|in:BDT,USD','opening'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99']);return $this->change($r,'account_created',function($w)use($d){if(F::query($w,'accounts')->where('name',$d['name'])->exists())$this->fail('name','Account already exists.');F::insert($w,'accounts',['name'=>$d['name'],'kind'=>$d['kind'],'currency'=>$d['currency'],'opening_minor'=>F::minor($d['opening'])]);});}
 public function category(Request $r){$this->workspace($r);$d=$r->validate(['name'=>'required|string|max:120','kind'=>'required|in:income,expense']);return $this->change($r,'category_created',function($w)use($d){if(F::query($w,'categories')->where($d)->exists())$this->fail('name','Category already exists.');F::insert($w,'categories',$d);});}
 private function entryData(Request $r):array{return $r->validate(['account_id'=>'required|integer|min:1','category_id'=>'required|integer|min:1','kind'=>'required|in:income,expense','title'=>'required|string|max:200','amount'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99']);}
 private function entry(array $d):array{$d['amount_minor']=$this->positive($d['amount']);unset($d['amount']);return $d;}
 public function transaction(Request $r){$this->workspace($r);$d=$this->entryData($r)+$r->validate(['local_date'=>$this->dateRule($r)]);return $this->change($r,'transaction_posted',fn($w)=>F::post($w,$r->user(),$this->entry($d)));}
 public function reverse(Request $r,int $id){$this->workspace($r);$d=$r->validate(['reason'=>'required|string|max:160','local_date'=>$this->dateRule($r)]);return $this->change($r,'transaction_reversed',function($w)use($r,$id,$d){$t=F::row($w,'transactions',$id);if($t->reversal_of||F::query($w,'transactions')->where('reversal_of',$id)->exists())$this->fail('reason','Transaction already reversed or is a reversal.');if($d['local_date']<$t->local_date)$this->fail('local_date','Reversal cannot predate original.');if(F::query($w,'payroll')->where('transaction_id',$id)->exists()||F::query($w,'invoices')->where('transaction_id',$id)->exists())$this->fail('reason','Use a dedicated payment correction workflow; linked payments cannot be reversed here.');F::post($w,$r->user(),['account_id'=>$t->account_id,'category_id'=>$t->category_id,'kind'=>$t->kind==='income'?'expense':'income','title'=>'Reversal: '.$d['reason'],'amount_minor'=>$t->amount_minor,'local_date'=>$d['local_date'],'reversal_of'=>$id]);});}
 public function recurring(Request $r){$this->workspace($r);$d=$this->entryData($r)+$r->validate(['frequency'=>'required|in:daily,weekly,monthly','next_date'=>'required|date_format:Y-m-d|after_or_equal:'.$this->today($r).'|before_or_equal:2100-12-31']);return $this->change($r,'recurring_created',function($w)use($r,$d){F::row($w,'accounts',$d['account_id']);$c=F::row($w,'categories',$d['category_id']);abort_unless($c->kind===$d['kind'],422);F::insert($w,'recurring',$this->entry($d)+['user_id'=>$r->user()->id,'anchor_day'=>(int)substr($d['next_date'],-2),'timezone'=>$r->user()->timezone?:'UTC']);});}
 public function pause(Request $r,int $id){return $this->change($r,'recurring_paused',function($w)use($id){F::row($w,'recurring',$id);F::query($w,'recurring')->where('id',$id)->update(['active'=>false,'updated_at'=>now()]);});}
 public function rate(Request $r){$this->workspace($r);$d=$r->validate(['local_date'=>$this->dateRule($r),'bdt_per_usd'=>'required|string|regex:/^\d{1,6}(?:\.\d{1,6})?$/D']);return $this->change($r,'rate_recorded',function($w)use($d){if((float)$d['bdt_per_usd']<=0)$this->fail('bdt_per_usd','Rate must be positive.');F::query($w,'rates')->updateOrInsert(['workspace_id'=>$w->id,'local_date'=>$d['local_date']],['bdt_per_usd'=>$d['bdt_per_usd'],'created_at'=>now(),'updated_at'=>now()]);});}
 public function budget(Request $r){$this->workspace($r);$d=$r->validate(['category_id'=>'required|integer|min:1','month'=>$this->monthRule(),'currency'=>'required|in:BDT,USD','amount'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99']);return $this->change($r,'budget_saved',function($w)use($d){$c=F::row($w,'categories',$d['category_id']);abort_unless($c->kind==='expense',422);F::query($w,'budgets')->updateOrInsert(['workspace_id'=>$w->id,'category_id'=>$c->id,'month'=>$d['month'].'-01','currency'=>$d['currency']],['limit_minor'=>$this->positive($d['amount']),'created_at'=>now(),'updated_at'=>now()]);});}
 public function savings(Request $r){$this->workspace($r);$d=$r->validate(['name'=>'required|string|max:200','currency'=>'required|in:BDT,USD','amount'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99','due_date'=>'nullable|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:2100-12-31']);return $this->change($r,'savings_created',function($w)use($d){F::insert($w,'savings',['name'=>$d['name'],'currency'=>$d['currency'],'target_minor'=>$this->positive($d['amount']),'due_date'=>$d['due_date']??null]);});}
 public function savingsProgress(Request $r,int $id){$this->workspace($r);$d=$r->validate(['amount'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99']);return $this->change($r,'savings_updated',function($w)use($id,$d){F::row($w,'savings',$id);F::query($w,'savings')->where('id',$id)->update(['saved_minor'=>F::minor($d['amount']),'updated_at'=>now()]);});}
 public function salary(Request $r){$this->business($this->workspace($r));$d=$r->validate(['user_id'=>'required|integer|min:1','currency'=>'required|in:BDT,USD','amount'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99']);return $this->change($r,'salary_saved',function($w)use($d){$this->business($w);TeamAccess::target($w,$d['user_id']);F::query($w,'salaries')->updateOrInsert(['workspace_id'=>$w->id,'user_id'=>$d['user_id']],['currency'=>$d['currency'],'base_minor'=>$this->positive($d['amount']),'created_at'=>now(),'updated_at'=>now()]);});}
 public function payroll(Request $r){$this->business($this->workspace($r));$d=$r->validate(['salary_id'=>'required|integer|min:1','month'=>$this->monthRule(),'bonus'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99','deduction'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99']);return $this->change($r,'payroll_created',function($w)use($d){$this->business($w);$s=F::row($w,'salaries',$d['salary_id']);TeamAccess::target($w,$s->user_id);$month=$d['month'].'-01';if(F::query($w,'payroll')->where('user_id',$s->user_id)->where('month',$month)->exists())$this->fail('month','Payroll already exists for employee and month.');$bonus=F::minor($d['bonus']);$deduction=F::minor($d['deduction']);$net=(int)$s->base_minor+$bonus-$deduction;if($net<=0)$this->fail('deduction','Net salary must be positive.');F::insert($w,'payroll',['user_id'=>$s->user_id,'month'=>$month,'currency'=>$s->currency,'base_minor'=>$s->base_minor,'bonus_minor'=>$bonus,'deduction_minor'=>$deduction,'net_minor'=>$net]);});}
 public function invoice(Request $r){$this->business($this->workspace($r));$d=$r->validate(['contact_id'=>'required|integer|min:1','title'=>'required|string|max:200','description'=>'required|string|max:10000','currency'=>'required|in:BDT,USD','amount'=>'required|numeric|decimal:0,2|min:0|max:9999999999.99','issue_date'=>$this->dateRule($r),'due_date'=>'required|date_format:Y-m-d|after_or_equal:issue_date|before_or_equal:2100-12-31']);return $this->change($r,'invoice_created',function($w)use($d){$this->business($w);$c=DB::table('crm_contacts')->where('workspace_id',$w->id)->where('id',$d['contact_id'])->first();abort_unless($c,404);F::insert($w,'invoices',['contact_id'=>$c->id,'customer_name'=>$c->name,'title'=>$d['title'],'description'=>$d['description'],'currency'=>$d['currency'],'amount_minor'=>$this->positive($d['amount']),'issue_date'=>$d['issue_date'],'due_date'=>$d['due_date']]);});}
 private function payment(Request $r,int $id,string $table,string $kind){$this->business($this->workspace($r));$d=$r->validate(['account_id'=>'required|integer|min:1','category_id'=>'required|integer|min:1','local_date'=>$this->dateRule($r)]);return $this->change($r,$table.'_paid',function($w)use($r,$id,$table,$kind,$d){$this->business($w);$record=F::row($w,$table,$id);if($record->transaction_id)$this->fail('account_id','Payment already recorded.');$a=F::row($w,'accounts',$d['account_id']);if($a->currency!==$record->currency)$this->fail('account_id','Account currency must match payment.');$earliest=$table==='payroll'?$record->month:$record->issue_date;if($d['local_date']<$earliest)$this->fail('local_date','Payment cannot predate record.');$tx=F::post($w,$r->user(),$d+['title'=>($table==='payroll'?'Payroll':'Invoice').' #'.$id,'kind'=>$kind,'amount_minor'=>$table==='payroll'?$record->net_minor:$record->amount_minor]);F::query($w,$table)->where('id',$id)->update(['transaction_id'=>$tx,'updated_at'=>now()]);});}
 public function payPayroll(Request $r,int $id){return $this->payment($r,$id,'payroll','expense');}
 public function payInvoice(Request $r,int $id){return $this->payment($r,$id,'invoices','income');}
 public function printInvoice(Request $r,int $id){$w=$this->workspace($r);$this->business($w);$invoice=F::row($w,'invoices',$id);return view('finance.invoice',compact('w','invoice'));}
 public function upload(Request $r,int $id){$w=$this->workspace($r);F::row($w,'transactions',$id);$d=$r->validate(['file'=>'required|file|max:5120|mimes:pdf,png,jpg,jpeg,txt|extensions:pdf,png,jpg,jpeg,txt']);$file=$d['file'];$path=$file->store('finance-receipts/'.$w->id,'local');abort_unless($path,503);try{return $this->change($r,'receipt_uploaded',function($w)use($id,$file,$path){F::row($w,'transactions',$id);abort_if(F::query($w,'receipts')->where('transaction_id',$id)->count()>=20,422);$name=mb_substr(preg_replace('/[\x00-\x1f\x7f]/u','',basename(str_replace('\\','/',$file->getClientOriginalName())))?:'receipt',0,200);F::insert($w,'receipts',['transaction_id'=>$id,'path'=>$path,'name'=>$name,'size'=>$file->getSize()]);});}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}}
 public function download(Request $r,int $id){$w=$this->workspace($r);$receipt=F::row($w,'receipts',$id);F::row($w,'transactions',$receipt->transaction_id);abort_unless(Storage::disk('local')->exists($receipt->path),404);return Storage::disk('local')->download($receipt->path,$receipt->name,['Content-Type'=>'application/octet-stream','X-Content-Type-Options'=>'nosniff']);}
 public function export(Request $r){$w=$this->workspace($r);$month=$this->month($r);$u=$r->user();return response()->streamDownload(function()use($w,$month,$u){F::authorize($w->fresh(),$u);$out=fopen('php://output','w');fputcsv($out,['ID','Date','Title','Direction','Currency','Amount','Account ID','Category ID','Reversal of'],',','"','');foreach(F::query($w,'transactions')->whereBetween('local_date',[$month.'-01',$this->end($month)])->orderBy('id')->cursor() as $t){$title=preg_match('/^[\s\x00-\x1f]*[=+\-@]/u',$t->title)||preg_match('/^[\t\r\n]/',$t->title)?"'".$t->title:$t->title;fputcsv($out,[$t->id,$t->local_date,$title,$t->kind,$t->currency,F::money($t->amount_minor),$t->account_id,$t->category_id,$t->reversal_of],',','"','');}fclose($out);},'ledger-'.$month.'.csv',['Content-Type'=>'text/csv; charset=UTF-8','Cache-Control'=>'no-store, private','X-Content-Type-Options'=>'nosniff']);}
}
